  "findings": [
    {
      "benefit": "Death",
      "years": [2016, 2019],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "~0.35 A/E peak-to-trough swings",
      "confidence": 0.85,
      "evidence": [
        "ae_death_by_year.csv: A/E swings from 0.86 (2016) to 1.22 (2017/2019) before reverting to ~0.94 in 2020-2024; empirical YoY SD 0.166 vs Poisson 0.048 (3.5x overdispersion); evidence pack flags SHAPED-OSCILLATING with max 1-yr move exceeding net excursion."
      ],
      "recommended_action": "Review claims coding and underwriting consistency for 2016-2019; assess whether swings reflect temporary data/reporting artifacts or transient mortality drivers; monitor recent years for stabilization."
    },
    {
      "benefit": "IP",
      "years": [2017, 2019],
      "pattern": "shock",
      "direction": "decrease",
      "magnitude": "~-0.34 A/E (drop from ~1.10 to ~0.76)",
      "confidence": 0.9,
      "evidence": [
        "ae_ip_by_year.csv: sharp drop in 2017 to 0.769, flat through 2019 (0.741-0.756), then snap-back to ~1.07 in 2020; evidence pack flags SHAPED-PULSE (excursion score 24.5, onset ratio 1.14) confirming abrupt arrival without gradual build-up."
      ],
      "recommended_action": "Investigate 2017-2019 claim volume drivers (e.g., benefit design changes, economic conditions, claims handling practices, or policyholder behavior shifts); validate pricing and reserving assumptions if structural break is confirmed."
    }
  ]
}

